values.headerSass:
.custom-header {
  h2, h3 {
font-size:80%;
}


.first-tier {
    height: 55px;
    width: 100%;
    line-height: 45px;
    text-align: center;
    margin-bottom: 0px;

  }

  .first-tier .nav>li>a:focus,
  .first-tier .nav>li>a:hover {
    border-bottom:2px solid #fff;
    background-color: #001E29;
  }
 .first-tier .nav>li>a{
background-color: #001E29;
}

  .first-tier h1 {
    display: inline;
    font-size: 25px;
    text-shadow: 1px 1px;
  }

  #banner {
         background-color: #001E29;
    background-repeat: no-repeat;
    background-position: right center;
     position:fixed;
     top: 0px;
     left: 0px;
     right: 0px;
     width: 100%;
     height: 67px;
     }

  }

values.footerSass:
.custom-footer {
  .footer-background {
    padding-top: 20px;
    padding-bottom: 20px;
    background-color: #001e29;
  }

  .logo, .nav {
    margin-bottom: 10px;
  }

  .nav-pills {
      display: flex;
      justify-content: center;
  }
  .container {
      font-size: 12px;
      color: grey;
  }
  .row-links {

      padding-left: 10px;
      padding-right: 10px;
  }
    .row-contact {

      padding: 10px;

  }

  }
